<script setup lang="ts">
import { computed,getCurrentInstance,nextTick,ref } from 'vue'
import { onLoad,onHide,onUnload,onBackPress } from '@dcloudio/uni-app'
import BrandLogo from '../../components/BrandLogo.vue'
import AppTabbar from '../../components/AppTabbar.vue'
import AppSheet from '../../components/AppSheet.vue'
import AppIcon from '../../components/AppIcon.vue'
import { api } from '../../services/api'
import type { Story } from '../../types/domain'
import { clampTime,cueIndexAt,formatTime } from '../../utils/performance'
import { errorMessage,goPage,requireSession,showMessage } from '../../utils/navigation'
const instance=getCurrentInstance(),story=ref<Story|null>(null),error=ref(''),time=ref(28),duration=ref(34.1),playing=ref(false),sound=ref(false),subtitles=ref(true),autoNext=ref(true),speed=ref(1),settings=ref(false),fullscreen=ref(false)
const media=computed(()=>story.value?.media),cues=computed(()=>media.value?.cues||[]),cueIndex=computed(()=>cueIndexAt(cues.value,time.value)),cue=computed(()=>cues.value[cueIndex.value]),actor=computed(()=>media.value?.actors.find(a=>a.id===cue.value?.speakerId)||{id:cue.value?.speakerId||'',name:cue.value?.kind==='action'?'动作分镜':cue.value?.kind==='sfx'?'音效':'旁白',portraitUrl:'/static/figma/ai-avatar.png'})
let timer:ReturnType<typeof setInterval>|undefined,lastTick=0
const video=()=>uni.createVideoContext('performance-video',instance?.proxy)
function pause(){playing.value=false;clearInterval(timer);timer=undefined;if(media.value?.videoUrl)video().pause()}
function ended(){pause();time.value=duration.value}
function selectCue(index:number){const item=cues.value[Math.max(0,Math.min(cues.value.length-1,index))];if(item)seek(item.start)}
function seek(value:number){time.value=clampTime(value,duration.value);if(media.value?.videoUrl)video().seek(time.value)}
function togglePlay(){
  if(playing.value){pause();return}
  if(time.value>=duration.value)seek(0)
  playing.value=true
  if(media.value?.videoUrl){video().play();return}
  lastTick=Date.now();clearInterval(timer)
  timer=setInterval(()=>{const now=Date.now(),next=clampTime(time.value+(now-lastTick)/1000*speed.value,duration.value);lastTick=now;const currentCue=cue.value;if(!autoNext.value&&currentCue&&next>=currentCue.end){time.value=currentCue.end-.01;pause();return}time.value=next;if(next>=duration.value)ended()},100)
}
function changeSpeed(rate:number){speed.value=rate;if(media.value?.videoUrl)video().playbackRate(rate)}
async function openFullscreen(){if(media.value?.videoUrl){await nextTick();video().requestFullScreen({direction:90})}else fullscreen.value=true}
function mediaTime(e:Event|{detail:{currentTime:number;duration:number}}){const detail=(e as {detail:{currentTime:number;duration:number}}).detail;if(!detail)return;duration.value=detail.duration||media.value?.duration||0;const next=clampTime(detail.currentTime,duration.value);if(!autoNext.value&&playing.value&&cue.value&&next>=cue.value.end){video().seek(cue.value.end-.01);pause();return}time.value=next}
function changeSubtitles(e:unknown){subtitles.value=!!(e as {detail:{value:boolean}}).detail.value}
function changeAutoNext(e:unknown){autoNext.value=!!(e as {detail:{value:boolean}}).detail.value}
function mediaError(){pause();error.value='视频暂时无法播放，请稍后重试'}
onLoad(async q=>{if(!requireSession())return;try{story.value=await api.story(String(q?.id||'demo-performance-001'));if(!story.value.media)throw new Error('这份故事还没有演绎内容');duration.value=story.value.media.duration;time.value=story.value.media.videoUrl?0:clampTime(28,duration.value);sound.value=!!story.value.media.videoUrl}catch(e){error.value=errorMessage(e)}})
onHide(pause);onUnload(pause);onBackPress(()=>{if(fullscreen.value){fullscreen.value=false;return true}return false})
</script>
<template><view class="performance-page"><image class="performance-background" src="/static/figma/home-background.png" mode="aspectFill"/><view class="performance-header"><BrandLogo variant="performance"/><text class="season-stamp">秋记</text></view><view v-if="error" class="paper-panel performance-error"><text class="error-copy">{{error}}</text><button class="outline-button full-button" @tap="error='';showMessage('可返回作品后重新打开演绎')">知道了</button></view><template v-if="media"><view class="cast-panel"><button class="work-heading" @tap="goPage('detail',{id:story?.id||''})"><view class="work-book"><AppIcon name="book-open" :size="22"/></view><view class="work-copy"><text class="work-title serif">{{story?.title}} · 剧本演绎</text><text class="small-note">{{media.videoUrl?'真实声音 · 分镜待审核':'演绎预览 · 当前版本'}}</text></view><AppIcon name="chevron-right" :size="20"/></button><view class="cast-label row-between"><text>{{media.videoUrl?'本章声音角色':'本章出场角色'}}</text><text class="small-note">{{media.actors.length}} 位角色</text></view><view class="cast-grid"><button v-for="(item,index) in media.actors" :key="item.id" class="cast-card" :class="{selected:actor?.id===item.id}" :aria-label="`选择${item.name}`" @tap="selectCue(cues.findIndex(c=>c.speakerId===item.id))"><image :src="item.portraitUrl" mode="aspectFit"/><text>{{item.name}}</text></button></view></view><view class="stage-panel"><video v-if="media.videoUrl" id="performance-video" class="stage-video" :src="media.videoUrl" :poster="media.posterUrl" :muted="!sound" :controls="true" object-fit="contain" @timeupdate="mediaTime" @ended="ended" @play="playing=true" @pause="playing=false" @error="mediaError"/><image v-else class="stage-poster" :src="media.posterUrl" mode="aspectFit"/><text v-if="!media.videoUrl" class="stage-badge">场景预览</text><button class="stage-fullscreen" aria-label="全屏查看" @tap="openFullscreen"><AppIcon name="maximize" :size="24" :light="true"/></button></view><view class="dialogue-panel"><view class="dialogue-heading row-between"><text>{{actor?.name}}</text><text class="small-note">{{cue?.kind==='action'?'动作原文':cue?.kind==='sfx'?'当前音效':'当前对白'}}</text></view><view class="dialogue-row"><image v-if="actor" class="speaker-portrait" :src="actor.portraitUrl" mode="aspectFit"/><view class="dialogue-bubble"><text>{{subtitles?cue?.text:'字幕已关闭'}}</text></view></view><view class="playback-section"><button class="sound-row" :aria-pressed="sound" @tap="sound=!sound"><AppIcon name="volume-2" :size="18"/><text>声音</text><text class="small-note">{{media.videoUrl?(sound?'开启':'关闭'):'暂未提供配音'}}</text></button><view class="time-row"><slider :value="time" :max="duration" :step="0.1" activeColor="#bc4d31" blockColor="#bc4d31" backgroundColor="#e4d5c7" :block-size="18" aria-label="演绎进度" @changing="seek($event.detail.value)" @change="seek($event.detail.value)"/><text>{{formatTime(time)}} / {{formatTime(duration)}}</text></view><view class="playback-controls"><button aria-label="上一句" @tap="selectCue(cueIndex-1)"><view class="control-pill"><AppIcon name="skip-back" :size="20"/></view><text>上一句</text></button><button class="main-play" :aria-label="playing?'暂停播放':'开始播放'" @tap="togglePlay"><view class="play-circle"><AppIcon :name="playing?'pause':'play'" :size="29" :light="true"/></view><text>{{playing?'暂停播放':'开始播放'}}</text></button><button aria-label="下一句" @tap="selectCue(cueIndex+1)"><view class="control-pill"><AppIcon name="skip-forward" :size="20"/></view><text>下一句</text></button><button aria-label="播放设置" @tap="settings=true"><view class="settings-circle"><AppIcon name="sliders-horizontal" :size="22"/></view><text>播放设置</text></button></view><text v-if="!media.videoUrl" class="preview-note">当前展示场景与对白，播放操作演示时间轴。</text></view></view></template><AppTabbar active="stories" tone="warm"/><AppSheet title="播放设置" :open="settings" @close="settings=false"><text class="field-label">播放速度</text><view class="chip-list"><button v-for="rate in [0.8,1,1.25]" :key="rate" class="chip" :class="{selected:speed===rate}" @tap="changeSpeed(rate)">{{rate}}×</button></view><view class="setting-row"><text>显示当前对白</text><switch :checked="subtitles" color="#b7432d" @change="changeSubtitles($event)"/></view><view class="setting-row"><text>自动进入下一句</text><switch :checked="autoNext" color="#b7432d" @change="changeAutoNext($event)"/></view></AppSheet><view v-if="fullscreen&&media" class="fullscreen-overlay"><view class="fullscreen-body"><image class="fullscreen-poster" :src="media.posterUrl" mode="aspectFit"/><button class="fullscreen-back" aria-label="退出全屏" @tap="fullscreen=false"><AppIcon name="minimize" :size="24" :light="true"/></button><text class="fullscreen-title">{{story?.title}} · 演绎预览</text><view class="fullscreen-bottom"><text v-if="subtitles" class="fullscreen-subtitle">{{actor?.name}}：{{cue?.text}}</text><view class="fullscreen-controls"><button aria-label="全屏上一句" @tap="selectCue(cueIndex-1)"><AppIcon name="skip-back" :size="22" :light="true"/></button><button :aria-label="playing?'全屏暂停':'全屏播放'" @tap="togglePlay"><AppIcon :name="playing?'pause':'play'" :size="26" :light="true"/></button><button aria-label="全屏下一句" @tap="selectCue(cueIndex+1)"><AppIcon name="skip-forward" :size="22" :light="true"/></button><slider :value="time" :max="duration" :step="0.1" :block-size="16" activeColor="#cf502a" @change="seek($event.detail.value)"/><text>{{formatTime(time)}} / {{formatTime(duration)}}</text></view></view></view></view></view></template>
