x;color:#fff6e7;background:#211a1680;border-radius:10rpx;padding:6rpx 12rpx;font-size:19rpx}.dialogue-panel{padding:25rpx 22rpx 24rpx;min-height:560rpx;display:flex;flex-direction:column}.dialogue-heading{padding-left:126rpx;font-size:29rpx;font-weight:700;margin-bottom:14rpx}.dialogue-heading .small-note{font-size:20rpx;font-weight:400;color:#b18168}.dialogue-row{display:flex;gap:18rpx;align-items:flex-start}.speaker-portrait{width:108rpx;height:122rpx;background:#f4e3ce;border:2rpx solid #e6c4a3;border-radius:20rpx}.dialogue-bubble{flex:1;min-height:132rpx;padding:20rpx 23rpx;background:#fffdf6;border:2rpx solid #ebcbb0;border-radius:22rpx;color:#793b28;font-size:29rpx;line-height:1.75;font-weight:700}.playback-section{margin-top:auto;padding-top:125rpx}.sound-row{display:flex;align-items:center;gap:15rpx;background:#fffbf2;border:2rpx solid #ead0b9;border-radius:17rpx;padding:15rpx 20rpx;text-align:left;font-size:25rpx}.sound-row .small-note{font-size:21rpx}.time-row{display:flex;align-items:center;gap:8rpx;margin:16rpx 0 4rpx}.time-row slider{flex:1;min-width:0;margin:10rpx 2rpx}.time-row>text{font-size:18rpx;color:#b18168;white-space:nowrap}.playback-controls{display:flex;align-items:center;justify-content:space-between;gap:15rpx}.playback-controls>button{display:flex;flex:1;flex-direction:column;align-items:center;gap:12rpx;font-size:24rpx;color:#ae402b;padding:10rpx 0}.control-pill{display:flex;align-items:center;justify-content:center;width:120rpx;height:50rpx;border:2rpx solid #edc4a5;border-radius:99rpx;background:#f8e7d5}.play-circle{height:80rpx;width:80rpx;display:flex;align-items:center;justify-content:center;background:#c65438;border:5rpx solid #fff2dd;border-radius:50%;box-shadow:0 0 0 7rpx #edccb4}.settings-circle{height:56rpx;width:56rpx;border-radius:50%;background:#fffaf0;border:2rpx solid #edc4a5;display:flex;align-items:center;justify-content:center}.preview-note{display:block;text-align:center;color:#b18168;font-size:18rpx;margin-top:12rpx}.setting-row{display:flex;align-items:center;justify-content:space-between;padding:30rpx 0;border-bottom:2rpx solid #eadcc9}.performance-error{position:relative;margin-bottom:20rpx}.fullscreen-overlay{position:fixed;inset:0;background:#171310;z-index:100}.fullscreen-body{position:absolute;left:50%;top:50%;width:100vw;height:100vh;transform:translate(-50%,-50%);color:white;overflow:hidden}.fullscreen-poster{width:100%;height:100%}.fullscreen-back{position:absolute;right:18px;top:12px;min-height:44px;min-width:44px;padding:10px;background:#211a1688;border:1px solid #e4c099;border-radius:50%}.fullscreen-title{position:absolute;left:22px;top:23px;font-size:14px;font-weight:700;text-shadow:0 1px 4px #000}.fullscreen-bottom{position:absolute;bottom:0;left:0;right:0;padding:12px 24px;background:#211a16dc}.fullscreen-subtitle{display:block;text-align:center;font-size:14px;line-height:1.6;min-height:24px}.fullscreen-controls{display:flex;align-items:center;gap:12px;margin-top:8px}.fullscreen-controls button{min-height:44px;min-width:44px;display:flex;align-items:center;justify-content:center}.fullscreen-controls slider{flex:1;min-width:70px;margin:0 10px}.fullscreen-controls>text{font-size:12px;white-space:nowrap}@media(orientation:portrait){.fullscreen-body{width:100vh;height:100vw;transform:translate(-50%,-50%) rotate(90deg)}}
</style>
<style scoped>
.work-heading{height:108rpx;padding:12rpx 24rpx}.work-book{width:62rpx;height:62rpx;padding:0;display:flex;align-items:center;justify-content:center;flex-shrink:0}.work-title{font-size:30rpx;line-height:38rpx}.work-copy .small-note{line-height:29rpx}.cast-label{height:50rpx;padding:0 24rpx;font-size:25rpx}.cast-card{height:120rpx;display:flex;flex-direction:column;line-height:1}.cast-card.selected{border-width:2rpx;box-shadow:inset 0 0 0 2rpx #b44834}.cast-card image{height:85rpx}.cast-card text{width:100%;flex:1;line-height:29rpx;padding:0;font-size:23rpx}.stage-poster,.stage-video{height:400rpx}.stage-panel{line-height:0}.dialogue-panel{height:612rpx;min-height:612rpx;padding:20rpx 20rpx 16rpx}.dialogue-heading{font-size:27rpx;line-height:32rpx;margin-bottom:12rpx}.speaker-portrait{height:122rpx;width:108rpx}.dialogue-bubble{min-height:132rpx;padding:17rpx 22rpx;font-size:27rpx;line-height:44rpx}.playback-section{padding-top:0}.sound-row{height:60rpx;padding:8rpx 16rpx;font-size:24rpx}.time-row{height:38rpx;margin:13rpx 0 4rpx}.playback-controls>button{height:128rpx;justify-content:center;font-size:23rpx;padding:8rpx 0;gap:10rpx}.preview-note{font-size:18rpx;line-height:22rpx;margin-top:5rpx}.season-stamp{width:47rpx;line-height:1.3;word-break:break-all}
